import { test, expect } from '@playwright/test';

test.describe('Product Detail Page Navigation', () => {
  test('should navigate to the product detail page and return to the catalogue', async ({ page }) => {
    await test.beforeEach(async ({ page }) => {
      await page.goto('https://www.saucedemo.com/inventory_items.html');
      await page.fill('#user_name', 'standard_user');
      await page.fill('#user_password', 'secret_sauce');
      await page.click('input[data-test="submit_user"]');
    });

    await page.click('.inventory_item_name');
    await expect(page).toHaveURL(/.*inventory-item.html/);
    await page.click('a[data-test="back-to-products"]');
    await expect(page).toHaveURL(/.*inventory.html/);
    await expect(page.locator('a#title')).toBeVisible();
    await expect(page.locator('a#title')).toHaveText('Products');
  });

  test('should not change the URL when clicking the back button with no product selected', async ({ page }) => {
    await test.beforeEach(async ({ page }) => {
      await page.goto('https://www.saucedemo.com/inventory_items.html');
    });

    await page.click('a[data-test="back-to-products"]');
    await expect(page).toHaveURL(/.*inventory.html/);
    await expect(page.locator('a#title')).toBeVisible();
    await expect(page.locator('a#title')).toHaveText('Products');
  });
});
